import { closeManagedPool, getOrCreateManagedPool, supabaseSsl, type PoolEnvConfig } from '@cbrl/pg'
import { drizzle, type NodePgDatabase } from 'drizzle-orm/node-postgres'
import { readFile } from 'node:fs/promises'
import type { Pool } from 'pg'
import * as schema from '../../contract/web/schema'

/**
 * Postgres connection for gabar (Supabase in production, docker locally/CI).
 *
 * The site only touches the `web` schema: views over published exams plus the
 * `web.join_waitlist` function, generated by the data pipeline into
 * `contract/web/`. In production `GABAR_DATABASE_URL` is the Supabase pooler
 * connection string (transaction mode) of a role restricted to that schema;
 * locally and in CI it is a plain URL to a database built from
 * `web.schema.sql`. Pool policy and the pinned Supabase CA come from
 * `@cbrl/pg`. Nothing connects until the first call.
 */
const poolConfig: PoolEnvConfig = {
  connectionStringEnvVar: 'GABAR_DATABASE_URL',
  database: 'gabar',
  ssl: supabaseSsl,
}

export type GabarDb = NodePgDatabase<typeof schema>

const pool = (): Pool => getOrCreateManagedPool(poolConfig).pool

let cached: { pool: Pool; db: GabarDb } | undefined

/** Drizzle client bound to the `web` contract schema. Lazily opens the pool. */
export function getGabarDb(): GabarDb {
  const current = pool()
  if (cached?.pool !== current) cached = { pool: current, db: drizzle(current, { schema }) }
  return cached.db
}

/** Round-trip `select 1` — health check, and the daily keep-alive for Supabase Free. */
export async function pingGabarDb(): Promise<void> {
  await pool().query('select 1')
}

/** Close the pool (tests / graceful shutdown). No-op if never opened. */
export const closeGabarDb = (): Promise<void> => closeManagedPool(poolConfig)

/**
 * Rebuild the `web` contract (`contract/web/web.schema.sql`) on a LOCAL test
 * database, dropping whatever was there. Used by the integration suite and the
 * local seed only: production `web` belongs to the data pipeline.
 */
export async function resetWebContract(): Promise<void> {
  const ddl = await readFile(new URL('../../contract/web/web.schema.sql', import.meta.url), 'utf8')
  await pool().query(
    `drop schema if exists web cascade; drop table if exists public.waitlist;\n${ddl}`,
  )
}
